let preferences=read(PREFS,{}),records={},metadata=read(META,{}),galleries=read(GALLERY,{}),visuals=read(VISUAL,{}),visualController,expandedWorks=false,visualYear='',catalog=[],view='all',filter='all',query='',shelf='',selected=null,searchItems=[],searchController,detailController,toastTimer,undoAction=null,draftRating=0,detailTab='overview',galleryController,activeGallery=[],activeGalleryIndex=0,activeGalleryItem=null;
