const portraitTasks=new Map(),portraitQueue=[];let portraitRunning=0;
function requestPortrait(id){if(portraitTasks.has(id))return portraitTasks.get(id);const task=new Promise(resolve=>{portraitQueue.push({id,resolve});pumpPortraits();});portraitTasks.set(id,task);return task;}
function pumpPortraits(){while(portraitRunning<2&&portraitQueue.length){const job=portraitQueue.shift();portraitRunning++;fillPortrait({id:job.id}).then(job.resolve,()=>job.resolve({})).finally(()=>{portraitRunning--;pumpPortraits();});}}
const portraitObserver=new IntersectionObserver(entries=>{for(const entry of entries)if(entry.isIntersecting){const image=entry.target;portraitObserver.unobserve(image);requestPortrait(image.dataset.missingPerson).then(result=>{if(!image.isConnected)return;if(result.image)image.src=thumbnailUrl(result.image,300,'portrait');else image.hidden=true;});}},{root:$('#detail-dialog'),rootMargin:'160px'});
function prepareVisualImages(){portraitObserver.disconnect();for(const image of $$('#visual-overview img')){image.onerror=async()=>{if(image.dataset.fallbackPerson&&!image.dataset.triedFallback){image.dataset.triedFallback='true';const result=await requestPortrait(image.dataset.fallbackPerson);if(image.isConnected&&result.image&&thumbnailUrl(result.image,300,'portrait')!==image.src){image.src=thumbnailUrl(result.image,300,'portrait');return;}}image.hidden=true;};if(image.dataset.missingPerson)portraitObserver.observe(image);}}
function syncMasthead(){if(!selected||!$('#detail-masthead'))return;const html=mastheadMarkup(selected);replaceMarkup($('#detail-masthead'),html);$('#detail-toolbar-title').textContent=displayName(selected);}
function updateVisualSections(){if(!selected||!$('#visual-overview'))return;if(replaceMarkup($('#visual-overview'),overviewMarkup(selected)))prepareVisualImages();syncMasthead();}

async function loadVisual(force=false){const item=selected;if(!item)return;const reference=metadata[item.id]?.item?.wikidata||item.wikidata||'',cached=visuals[item.id];if(!force&&cached?.version>=1&&cached.reference===reference&&Date.now()-Date.parse(cached.fetchedAt)<21600000){return;}if(item.kind==='character'){visuals[item.id]={version:1,reference,cast:[],crew:[],works:[],images:[],fetchedAt:new Date().toISOString()};updateVisualSections();return;}visualController?.abort();const controller=new AbortController();visualController=controller;try{const data=await visualDossier(item,metadata[item.id]||{},{signal:AbortSignal.any([controller.signal,AbortSignal.timeout(45000)])});if(controller.signal.aborted)return;visuals[item.id]={...data,reference};const latest=Object.entries(visuals).sort((a,b)=>Date.parse(b[1].fetchedAt)-Date.parse(a[1].fetchedAt)).slice(0,16);visuals=Object.fromEntries(latest);try{visuals=boundedCache(visuals,16,350000,item.id);localStorage.setItem(VISUAL,JSON.stringify(visuals));}catch{}if(selected?.id===item.id){updateVisualSections();if($('#photo-grid')){updatePhotoGrid();if($('#gallery-state'))$('#gallery-state').textContent='已关联 '+availableImages(item).length+' 张图片 · 仅围绕本条目';}}}catch{if(!controller.signal.aborted&&selected?.id===item.id){const base=metadata[item.id]||{};visuals[item.id]={version:0,reference,cast:(base.credits||[]).filter(x=>x.role==='演员'),crew:(base.credits||[]).filter(x=>!['演员','代表作品'].includes(x.role)),works:(base.credits||[]).filter(x=>x.role==='代表作品'),images:[],fetchedAt:new Date().toISOString()};updateVisualSections();}}}
function handleVisualActions(e){const role=e.target.closest('[data-role-photo]');if(role){const credit=visuals[selected.id]?.[role.dataset.creditGroup]?.[Number(role.dataset.rolePhoto)];if(credit)openGallery(selected,[{url:credit.characterOriginal||credit.characterImage,thumbnail:credit.characterImage,title:credit.character,kind:'角色肖像',source:'TVmaze · 本作品对应角色',pageUrl:credit.reference,license:'版权归原权利人'}]);return true;}if(e.target.closest('[data-expand-cast]')){castExpanded=!castExpanded;replaceMarkup($('#visual-cast'),castMarkup(selected));prepareVisualImages();return true;}const jump=e.target.closest('[data-jump-photos]'),cast=e.target.closest('[data-visual-credit]'),work=e.target.closest('[data-visual-work]'),year=e.target.closest('[data-work-year]');if(e.target.closest('[data-open-notes]')){detailTab='notes';applyDetailTab();$('#record-nickname')?.focus({preventScroll:true});scrollDetailPanel();return true;}if(jump){commitDraft();detailTab='gallery';applyDetailTab();scrollDetailPanel();loadGallery(false);return true;}if(e.target.closest('[data-scroll-cast]')){detailTab='overview';applyDetailTab();$('#visual-cast')?.scrollIntoView({block:'start',behavior:'smooth'});return true;}if(e.target.closest('[data-scroll-works]')){detailTab='overview';applyDetailTab();$('#visual-works')?.scrollIntoView({block:'start',behavior:'smooth'});return true;}if(year){visualYear=year.dataset.workYear;replaceMarkup($('#visual-works'),worksMarkup(selected).replace(/^<section[^>]*>|<\/section>$/g,''));prepareVisualImages();return true;}if(e.target.closest('[data-expand-works]')){expandedWorks=!expandedWorks;replaceMarkup($('#visual-works'),worksMarkup(selected).replace(/^<section[^>]*>|<\/section>$/g,''));prepareVisualImages();return true;}const entry=cast?visuals[selected.id]?.[cast.dataset.creditGroup]?.[Number(cast.dataset.visualCredit)]:work?visuals[selected.id]?.works?.[Number(work.dataset.visualWork)]:null;if(entry){commitDraft();if(/^(tt|nm)\d+$/.test(entry.id||''))showDetail({...entry,source:entry.source||'Wikidata 精确关联'});else{$('#detail-dialog').close();showSearch();$('#global-search').value=entry.title;$('#search-type').value=cast?'person':'title';$('#search-form').requestSubmit();}return true;}return false;}

$('#detail-content').addEventListener('submit',async e=>{
 if(e.target.id!=='photo-import-form'||!selected)return;e.preventDefault();importController?.abort();const controller=new AbortController();importController=controller;const item=selected,button=e.target.querySelector('button');button.disabled=true;$('#photo-import-state').textContent='正在读取你选择的图片…';
 try{const urls=$('#photo-import-links').value.trim().split(/\s+/).filter(Boolean).slice(0,6),images=[];for(const url of urls)images.push(...await imagesFromLink(url,{signal:AbortSignal.any([controller.signal,AbortSignal.timeout(18000)])}));if(controller.signal.aborted||selected?.id!==item.id)return;importImages=cleanAlbum(images);renderImportPreview();}
 catch(error){if(!controller.signal.aborted&&selected?.id===item.id)$('#photo-import-state').textContent=error.message||'暂时无法读取，请使用图片地址';}
 finally{if(button.isConnected)button.disabled=false;}
});
function renderImportPreview(){const images=importImages.slice(0,PHOTO_BATCH);$('#photo-import-state').textContent=importImages.length?'已读到 '+importImages.length+' 张；本批 '+images.length+' 张，请选择。':'这批图片已处理完，可继续加入其他链接。';$('#photo-import-preview').innerHTML=images.map((image,i)=>`<label><img referrerpolicy="no-referrer" src="${esc(thumbnailUrl(image))}" alt="${esc(image.title)}" width="180" height="180" loading="lazy" decoding="async"><span><input type="checkbox" data-import-photo="${i}" checked> ${esc(image.kind)}</span></label>`).join('');$('#add-import-photos').hidden=!images.length;}
function addImportedPhotos(){if(!selected)return;const indices=$$('#photo-import-preview input:checked').map(input=>Number(input.dataset.importPhoto));if(!indices.length){toast('请先选中图片');return;}const chosen=indices.map(index=>importImages[index]),old=recordFor(selected).album,album=mergePhotos(old,chosen),added=album.length-old.length;saveRecord(selected,{album});importImages=importImages.slice(PHOTO_BATCH);renderImportPreview();updatePhotoGrid();updatePhotoRibbon();toast(added?'已收藏 '+added+' 张你选中的图片':'这些图片已经在你的相册中');}

function directStateMarkup(item){const state=galleries[item.id]?.sourceState||{};return Object.entries(DIRECT_SOURCES).map(([source,name])=>{const row=state[source],busy=directBusy.has(source),label=busy?'正在读取…':!row?'尚未请求':row.status==='ok'?row.lastAdded?'本次新增 '+row.lastAdded+' 张':'本次图片已收录':row.status==='empty'?'已读完，等待图库更新':row.status==='blocked'?'来源暂时限制访问':row.status==='unmatched'?'暂无该条目图库':row.message||'暂不可用';return `<span data-source-result="${source}" class="${busy?'is-loading':''}"><b>${name}</b><small>${esc(label)}${row?.updatedAt?' · '+esc(new Date(row.updatedAt).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'})):''}${row?.method==='public-image-index'?' · 搜索索引':''}</small></span>`;}).join('');}
function photoAvailabilityMarkup(item){
 const id=photoSubjectId(item),check=photoChecks.get(id),task=photoTasks[id];
 if(!/^(tt|nm)\d{5,12}$/.test(id))return '<p class="quiet-copy">将角色关联到影视或人物后，可读取对应图库。</p>';
 if(task?.status==='waiting-network')return `<div class="photo-request-card"><span class="photo-request-symbol" aria-hidden="true">✧</span><div><h4>补图请求待发送</h4><p>暂时连不上补图服务，请求已保存在本机。</p><button class="button button-light" data-request-photos>重试连接 ↻</button><small>恢复连接或回到应用后会自动重试，已有图片与手记都会保留。</small></div></div>`;
 if(task&&['submitting','queued','processing'].includes(task.status))return `<div class="photo-request-card"><span class="photo-request-symbol" aria-hidden="true">✧</span><div><h4>${task.status==='submitting'?'正在提交补图…':task.status==='processing'?'正在采集这个条目的图片':'补图已排队'}</h4><p>你可以继续浏览，完成后会自动读取新图。</p><small>通常需要几分钟；GitHub 调度繁忙时可能延迟。</small></div></div>`;
 if(!check||check.status==='checking')return '<p class="quiet-copy">正在检查这个条目的图库…</p>';
 if(check.status==='missing')return `<div class="photo-request-card"><span class="photo-request-symbol" aria-hidden="true">✧</span><div><h4>${task?.status==='failed'?'本次补图未完成':'还没有这个条目的图库'}</h4><p>${task?.status==='failed'?esc(task.message||'上次采集未完成，可以再试一次。'):'在这里补图，采集完成后自动读取。'}</p><button class="button button-light" data-request-photos>为这个条目补图 ＋</button><small>仅提交公开 IMDb 编号，手记与评分留在本机。</small></div></div>`;
 if(check.status==='error')return `<p class="quiet-copy">${esc(check.message)}。你的已有图片仍可查看。</p>`;
 return `<details class="photo-request-details"><summary>想再补充这个条目的图片？</summary><p class="quiet-copy">${task?.status==='failed'?esc(task.message):'可在这里申请补图，完成后自动读取。'}</p><button class="text-button" data-request-photos>继续补图 ＋</button></details>`;
}
function updateDirectState(){
 if(!selected)return;const hasSubject=/^(tt|nm)\d+$/.test(photoSubjectId(selected)),check=photoChecks.get(photoSubjectId(selected)),ready=check?.status==='ready',checking=check?.status==='checking';
 const state=$('#direct-source-state');if(state){replaceMarkup(state,directStateMarkup(selected));state.hidden=!hasSubject||!!check&&!ready;}
 const availability=$('#photo-availability');if(availability)replaceMarkup(availability,photoAvailabilityMarkup(selected));
 const controls=$('#detail-content .direct-source-controls');if(controls)controls.hidden=!hasSubject||!!check&&!ready;
 const main=$('#refresh-gallery');if(main){main.hidden=!hasSubject;const task=photoTasks[photoSubjectId(selected)];main.disabled=directBusy.size>0||checking||task?.status==='submitting';main.textContent=task?.status==='waiting-network'?'重试连接 ↻':task&&['queued','processing'].includes(task.status)?'查看补图进度 ↻':directBusy.size?'正在读取三站图库…':checking?'正在检查图库…':ready?'从三站图库读取更多 ＋':check?.status==='missing'?'为这个条目补图 ＋':'重新读取图库 ↻';}
 for(const button of $$('#detail-content [data-fetch-source]'))button.disabled=directBusy.has(button.dataset.fetchSource)||checking;
}
async function checkPhotoAvailability(refresh=false){
 const item=selected;if(!item)return;const id=photoSubjectId(item);if(!/^(tt|nm)\d+$/.test(id)){updateDirectState();return;}
 const old=photoChecks.get(id);if(!refresh&&old&&(old.status==='checking'||Date.now()-old.at<60000)){updateDirectState();return;}
 photoChecks.set(id,{status:'checking',at:Date.now()});updateDirectState();
 try{const result=await fetchPhotoSource(item,{source:'imdb',refresh:refresh||photoTasks[id]?.status==='ready',signal:AbortSignal.timeout(16000)});photoChecks.set(id,{status:result.registered===false?'missing':'ready',at:Date.now(),dataAt:result.checkedAt||''});if(result.registered===false&&isCollected(recordFor(item))&&!photoTasks[id])queuePhotoTask(item,{quiet:true});if(result.registered!==false&&photoTasks[id]?.status==='waiting-network'&&(!photoTasks[id].previousDataAt||photoTasks[id].previousDataAt!==result.checkedAt)){photoTasks[id].status='ready';persistPhotoTasks();}if(result.registered!==false&&selected?.id===item.id){const sourceState=galleries[item.id]?.sourceState;for(const name of Object.keys(sourceState||{}))if(sourceState[name].status==='unavailable')delete sourceState[name];if((old?.status==='missing'||photoTasks[id]?.status==='ready')&&detailTab==='gallery'){if(photoTasks[id]?.status==='ready'){photoTasks[id].status='loaded';persistPhotoTasks();}loadDirectPhotos('all');}}}
 catch(error){photoChecks.set(id,{status:'error',message:error.message||'暂时无法连接图库',at:Date.now()});}
 if(selected&&photoSubjectId(selected)===id)updateDirectState();
}
function persistPhotoTasks(){try{localStorage.setItem('isolate.photo-tasks.v1',JSON.stringify(Object.fromEntries(Object.entries(photoTasks).slice(-60))));}catch{}}
function schedulePhotoTasks(){
 clearTimeout(photoTaskTimer);let delay=photoTaskDelay(photoTasks);if(delay===null||document.visibilityState==='hidden')return;
 if(navigator.onLine===false)delay=Math.max(delay,60000);photoTaskTimer=setTimeout(pollPhotoTasks,delay);
}
async function applyPhotoCompletion(id){
 photoTasks[id]={...photoTasks[id],status:'ready',message:''};photoChecks.delete(id);persistPhotoTasks();
 if(selected&&photoSubjectId(selected)===id){await checkPhotoAvailability(true);if(photoChecks.get(id)?.status==='ready'&&!directBusy.size)loadDirectPhotos('all');}
}
async function queuePhotoTask(item,{quiet=false}={}){
 const id=photoSubjectId(item);if(!/^(tt|nm)\d{5,12}$/.test(id||''))return;
 if(photoTasks[id]&&['submitting','queued','processing'].includes(photoTasks[id].status)){schedulePhotoTasks();return;}
 const prior=photoTasks[id]||{},waiting=prior.status==='waiting-network';
 if(quiet||waiting){try{const existing=await fetchPhotoSource(item,{source:'imdb',refresh:waiting,signal:AbortSignal.timeout(16000)});if(existing.registered!==false&&(!waiting||!prior.previousDataAt||prior.previousDataAt!==existing.checkedAt)){if(waiting)await applyPhotoCompletion(id);schedulePhotoTasks();return;}}catch{}}
 if(photoTasks[id]&&['submitting','queued','processing'].includes(photoTasks[id].status))return;
 const info={attempts:prior.attempts||0,intentAt:prior.intentAt||Date.now(),previousDataAt:prior.previousDataAt??photoChecks.get(id)?.dataAt??''};
 photoTasks[id]={...info,status:'submitting'};persistPhotoTasks();updateDirectState();
 try{
  if(navigator.onLine===false)throw Object.assign(Error('暂时无法连接补图服务'),{retryable:true});
  const result=await requestPhotoTask(id);photoTasks[id]={...info,...result};
  if(result.status==='done'){await applyPhotoCompletion(id);if(!quiet)toast('图库刚更新过，已重新读取');}
  else{persistPhotoTasks();if(!quiet)toast('补图已排队，完成后会自动读取');}
 }catch(error){photoTasks[id]={...info,...deferPhotoTask(info,error)};persistPhotoTasks();if(!quiet)toast(error.retryable?'请求已保存在本机，恢复连接后自动重试':error.message);}
 if(selected&&photoSubjectId(selected)===id)updateDirectState();schedulePhotoTasks();
}
async function pollPhotoTasks({retryNow=false}={}){
 if(photoPollBusy)return;clearTimeout(photoTaskTimer);if(navigator.onLine===false){schedulePhotoTasks();return;}photoPollBusy=true;
 try{
  const waiting=Object.entries(photoTasks).filter(([,task])=>task.status==='waiting-network'&&(retryNow||!task.retryAt||task.retryAt<=Date.now())).slice(0,4);
  await Promise.allSettled(waiting.map(([id])=>queuePhotoTask({id,kind:id.startsWith('nm')?'person':'film'},{quiet:true})));
  const pending=Object.entries(photoTasks).filter(([,task])=>['queued','processing'].includes(task.status)).slice(0,8);
  await Promise.allSettled(pending.map(async([id])=>{try{const result=await requestPhotoTask(id,{readOnly:true});photoTasks[id]={...photoTasks[id],...result};if(result.status==='done')await applyPhotoCompletion(id);}catch(error){photoTasks[id]={...photoTasks[id],message:error.message};}}));
 }finally{photoPollBusy=false;persistPhotoTasks();updateDirectState();schedulePhotoTasks();}
}
function resumePhotoTasks(){
 if(document.visibilityState==='hidden')return;for(const task of Object.values(photoTasks))if(task.status==='waiting-network')task.retryAt=Date.now();persistPhotoTasks();clearTimeout(photoTaskTimer);
 photoTaskTimer=setTimeout(()=>{pollPhotoTasks({retryNow:true});if(selected&&detailTab==='gallery')checkPhotoAvailability(true);},1000);
}
window.addEventListener('online',resumePhotoTasks);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')resumePhotoTasks();else clearTimeout(photoTaskTimer);});
persistPhotoTasks();schedulePhotoTasks();
async function loadDirectPhotos(source,{requestMore=false}={}){
 const item=selected;if(!item||directBusy.size)return;commitDraft();directController?.abort();const controller=new AbortController();directController=controller;const sources=source==='all'?Object.keys(DIRECT_SOURCES):[source];for(const name of sources)directBusy.add(name);updateDirectState();
 const subject={...item,...metadata[item.id]?.item};let totalAdded=0;
 await Promise.allSettled(sources.map(async name=>{
  const prior=galleries[item.id]?.sourceState?.[name]||{};
  try{const result=await fetchPhotoSource(subject,{source:name,cursor:prior.cursor,knownImages:galleries[item.id]?.images||[],signal:AbortSignal.any([controller.signal,AbortSignal.timeout(21000)])});if(controller.signal.aborted||selected?.id!==item.id)return;if(result.registered===false)photoChecks.set(photoSubjectId(item),{status:'missing',at:Date.now()});
   const current=galleries[item.id]||{},images=mergePhotos(current.images||[],result.images),added=images.length-(current.images||[]).length;totalAdded+=added;
   galleries[item.id]={...current,images,sourceState:{...current.sourceState,[name]:{status:result.status,cursor:result.status==='ok'||result.status==='empty'?result.nextCursor:prior.cursor||null,lastAdded:added,method:result.method,updatedAt:result.updatedAt,message:result.message||'',fetchedAt:new Date().toISOString()}},fetchedAt:new Date().toISOString()};
   try{galleries=boundedCache(galleries,24,480000,item.id);localStorage.setItem(GALLERY,JSON.stringify(galleries));}catch{}
   const directCount=images.filter(image=>/^(IMDb 相册|豆瓣 相册|Pinterest 搜索|IMDb · 搜索索引|豆瓣 · 搜索索引|Pinterest · 搜索索引)$/.test(image.source)).length;galleryVisible=Math.min(availableImages(item).length,Math.max(galleryVisible,directCount));updatePhotoGrid();updatePhotoRibbon();
  }catch(error){if(controller.signal.aborted||selected?.id!==item.id)return;const current=galleries[item.id]||{};galleries[item.id]={...current,sourceState:{...current.sourceState,[name]:{...prior,status:'unavailable',lastAdded:0,message:error.message||'请求失败'}}};}
  finally{if(selected?.id===item.id&&!controller.signal.aborted){directBusy.delete(name);updateDirectState();}}
 }));
 if(selected?.id===item.id&&!controller.signal.aborted){if($('#gallery-state'))$('#gallery-state').textContent=totalAdded?'本次从公开图库新增 '+totalAdded+' 张 · 已去重并保留已有图片':photoChecks.get(photoSubjectId(item))?.status==='missing'?'图库尚未建立，可在这里直接补图。':'当前没有新图片，可查看各站状态或前往原始页面。';updateDirectState();if(requestMore&&!totalAdded&&sources.some(name=>galleries[item.id]?.sourceState?.[name]?.status!=='complete'))queuePhotoTask(item);}
}
